{
  "interpretation": {
    "name": "Line1NutrunnerTighteningWithReturn",
    "scope": {"line": 1, "station": "st1", "tool": "NR7", "variant": "F25"},
    "goal": "Reserve the shared nutrunner NR7, bring it to station st1, tighten the F25 fasteners per the MES program, evaluate and record the result, return the tool to the crib and release the reservation.",
    "constraints": [
      "The tool is reserved exclusively before any use and released after it has been returned to the crib",
      "Every tool-using step renews the lease with the reservation token and depends on reserve-tool",
      "transport-tool is delegated to the executor agvexecutor",
      "The tool must be at the station before configure-tool and tighten-fasteners",
      "The tightening program comes only from get-program; no numeric process values appear in the recipe",
      "The tightening is evaluated against its program and recorded for traceability",
      "The tool is returned to the crib after use"
    ],
    "preference": "",
    "priority": "normal",
    "horizon": "one-shot, immediate execution for the current request",
    "requested_capabilities": [],
    "omit_services": []
  },
  "recipe": {
    "name": "line1-nr7-tightening-with-return",
    "first_action": "Prepare",
    "actions": [
      {
        "name": "Prepare",
        "next": "Deliver",
        "steps": [
          {
            "name": "reserve",
            "service": "reserve-tool",
            "next": [],
            "dep": [],
            "executor": null,
            "params": {}
          },
          {
            "name": "program",
            "service": "get-program",
            "next": [],
            "dep": [],
            "executor": null,
            "params": {}
          }
        ]
      },
      {
        "name": "Deliver",
        "next": "Tighten",
        "steps": [
          {
            "name": "transport-to-station",
            "service": "transport-tool",
            "next": [],
            "dep": ["reserve"],
            "executor": "agvexecutor",
            "params": {"to": "station"}
          }
        ]
      },
      {
        "name": "Tighten",
        "next": "Verify",
        "steps": [
          {
            "name": "configure",
            "service": "configure-tool",
            "next": ["tighten"],
            "dep": ["reserve", "program", "transport-to-station"],
            "executor": null,
            "params": {}
          },
          {
            "name": "tighten",
            "service": "tighten-fasteners",
            "next": [],
            "dep": ["reserve", "configure", "transport-to-station"],
            "executor": null,
            "params": {}
          }
        ]
      },
      {
        "name": "Verify",
        "next": "Return",
        "steps": [
          {
            "name": "evaluate",
            "service": "evaluate-tightening",
            "next": [],
            "dep": ["tighten", "program"],
            "executor": null,
            "params": {}
          },
          {
            "name": "record",
            "service": "record-tightening",
            "next": [],
            "dep": ["tighten"],
            "executor": null,
            "params": {}
          }
        ]
      },
      {
        "name": "Return",
        "next": null,
        "steps": [
          {
            "name": "transport-to-crib",
            "service": "transport-tool",
            "next": ["release"],
            "dep": ["reserve"],
            "executor": "agvexecutor",
            "params": {"to": "crib"}
          },
          {
            "name": "release",
            "service": "release-tool",
            "next": [],
            "dep": ["reserve"],
            "executor": null,
            "params": {}
          }
        ]
      }
    ]
  }
}
